do $$
declare n int;
begin
  select count(*) into n from tandem.order_menu
   where active and price_checked_at is not null and coalesce(btrim(title_kz), '') = '';
  if n > 0 then raise exception 'Без казахского названия осталось позиций: %', n; end if;
end $$;
